INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('caminhão', '2025-07-12 17:35:59', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.recursal.juizados.especiais.civeis.criminais.df.1:acordao:1999-06-29;117182', 'Acórdão nº 117182 do Processo nºacj84399', 'urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.recursal.juizados.especiais.civeis.criminais.df.1:acordao:1999-06-29;117182', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Justica Distrito Federal Territorios', 'Acordao', '1999-06-29', 'CONFIRMAÇÃO, INDENIZAÇÃO, ABALROAMENTO, AUTOMÓVEL, ESTACIONAMENTO; COMPROVAÇÃO, CULPA, MOTORISTA,CAMINHÃO, INDÍCIO, OBRIGATORIEDADE, RESSARCIMENTO.', 'ACIDENTE DE TRÂNSITO. REPARAÇÃO DE DANOS. INDÍCIOS COMO MEIOS DE PROVA. ABALROAMENTO EM ESTACIONAMENTO. INDENIZAÇÃO FIXADA COM BASE NO MENOR DOS ORÇAMENTOS.
I - CONSIDERA-SE INDÍCIO, SEGUNDO O ART. 239 DO CÓDIGO DE PROCESSO PENAL, QUE SE APLICA A TODO RAMO DO DIREITO, A CIRCUNSTÂNCIA CONHECIDA E PROVADA, QUE, TENDO RELAÇÃO COM O FATO, AUTORIZE, POR INDUÇÃO, CONCLUIR-SE A EXISTÊNCIA DE OUTRA OU OUTRAS CIRCUNSTÂNCIAS. EM FACE DOS INDÍCIOS, PODE-SE CHEGAR A CONCLUSÃO SATISFATÓRIA POR UMA CONSTRUÇÃO LÓGICA. ASSIM, SE UM VEÍCULO, EM PERFEITO ESTADO,  ESTACIONADO AO LADO DE UMCAMINHÃO, APARECE DANIFICADO, APÓS A SAÍDA DOCAMINHÃO, E NÃO TENDO NENHUM OUTRO SE POSICIONADO AO SEU LADO, POR CONSTRUÇÃO LÓGICA, CONCLUI-SE QUE FOI OCAMINHÃOO CAUSADOR DOS DANOS, SOBRETUDO QUANDO FICAR CONSTATADO QUE O SEU MOTORISTA TEVE DIFICULDADE PARA MANOBRÁ-LO NO ESTACIONAMENTO. II -  CERTIFICADA A CULPA DO MOTORISTA DOCAMINHÃO, POR MEIO DOS INDÍCIOS, IMPÕE-SE AO SEU PROPRIETÁRIO O DEVER DE INDENIZAR OS DANOS CAUSADOS NO AUTOMÓVEL, PODENDO TAL VALOR SER FIXADO COM BASE NO MENOR DOS ORÇAMENTOS APRESENTADOS.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('caminhão', '2025-07-12 17:35:59', 'https://www.lexml.gov.br/urn/urn:lex:br;minas.gerais:estadual:decreto:2013-12-30;46413', 'Decreto nº 46413, de 30 de dezembro de 2013', 'urn:lex:br;minas.gerais:estadual:decreto:2013-12-30;46413', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Estadual', '2013-12-30', 'REGULAMENTAÇÃO, PROGRAMA ESTADUAL, INCENTIVO, MODERNIZAÇÃO, 
