INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('caminhão', '2025-07-12 17:35:59', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.16:tribunal.regional.trabalho;turma.2:acordao:2013-07-02;0099100-96.2009.5.16.0015', 'ACORDÃO TRT 16ª / 2ª Turma / RO 0099100-96.2009.5.16.0015', 'urn:lex:br;justica.trabalho;regiao.16:tribunal.regional.trabalho;turma.2:acordao:2013-07-02;0099100-96.2009.5.16.0015', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 16', 'Tribunal Regional Trabalho', 'Acordao', '2013-07-02', 'ACIDENTE,ATIVIDADE,CAMINHÃO,CONTROLE,EXTERNO,EXTRAS,HORÁRIO,HORAS,INERENTE,INEXISTÊNCIA,MOTORISTA,OBJETIVA,RESPONSABILIDADE,RISCO,TRABALHO', 'ACIDENTE DE TRABALHO. MOTORISTA DECAMINHÃO. RISCO INERENTE À ATIVIDADE. RESPONSABILIDADE OBJETIVA. É inerente à atividade de motorista decaminhãoo risco de acidente de trânsito, ensejando a aplicação da responsabilidade objetiva, conforme o disposto no parágrafo único do art. 927, do Código Civil. Não se questiona de culpa do empregador, sendo necessária somente a comprovação do dano e a existência de nexo causal entre este e a atividade desempenhada pelo trabalhador para que surja o dever de indenizar danos morais e patrimoniais decorrentes do acidente de trabalho. Na hipótese, não restou configurada a força maior alegada pela defesa, visto que, na atividade desempenhada pelo reclamante, o choque com um animal na estrada, ainda que inevitável, é fato previsível, integrando o próprio risco da profissão. TRABALHO EXTERNO. MOTORISTA DECAMINHÃO. INEXISTÊNCIA DE CONTROLE DE HORÁRIO. HORAS EXTRAS. Comprovado o trabalho em atividade externa, na função de motorista decaminhão, sem o efetivo controle de horário pelo empregador, insere-se o empregado na exceção do inciso I do art. 62 da CLT, não fazendo jus a horas extras.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
