INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('caminhão', '2025-07-12 17:35:59', 'https://www.lexml.gov.br/urn/urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.recursal.juizados.especiais.civeis.criminais.df.1:acordao:1999-12-14;122998', 'Acórdão nº 122998 do Processo nº19990210010853acj', 'urn:lex:br;distrito.federal:tribunal.justica.distrito.federal.territorios;turma.recursal.juizados.especiais.civeis.criminais.df.1:acordao:1999-12-14;122998', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Justica Distrito Federal Territorios', 'Acordao', '1999-12-14', 'IMPROCEDÊNCIA,  INDENIZAÇÃO,  IRREGULARIDADE,  MOTOR,CAMINHÃO,  INOCORRÊNCIA,  COMPROVAÇÃO,  RESPONSABILIDADE,  ANTERIORIDADE,  PROPRIETÁRIO.', 'RESPONSABILIDADE CIVIL. IRREGULARIDADE CONSTATADA EM BLOCO DE MOTOR DECAMINHÃO. REPARAÇÃO EFETUADA POR EX-PROPRIETÁRIO. COBRANÇA REGRESSIVA IMPOSSÍVEL, NÃO SENDO COMPROVADA A RESPONSABILIDADE DOS EX-DONOS DO VEÍCULO.
A AÇÃO DE REGRESSO, QUE OBJETIVA O RESSARCIMENTO DE PREJUÍZOS SOFRIDOS COM A REPARAÇÃO DE IRREGULARIDADE EM BLOCO DE MOTOR DECAMINHÃO, QUE MOTIVOU A SUA APREENSÃO PELA POLÍCIA, SÓ PODERÁ SER JULGADA PROCEDENTE SE FICAR COMPROVADA A RESPONSABILIDADE DOS EX-DONOS DO VEÍCULO. INTELIGÊNCIA DO ART. 333, INC. I DO CÓDIGO DE PROCESSO CIVIL.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('frete', '2025-07-12 17:36:02', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2016-12-23;762', 'MPV 762/2016', 'urn:lex:br:congresso.nacional:medida.provisoria;mpv:2016-12-23;762', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Congresso Nacional', '2016-12-23', NULL, 'Altera a Lei nº 11.482, de 31 de maio de 2007, para prorrogar o prazo de vigência da não incidência do Adicional aoFretepara Renovação da Marinha Mercante - AFRMM previsto no art. 17 da Lei nº 9.432, de 8 de janeiro de 1997. 

NOVA EMENTA: Altera a Lei nº 11.482, de 31 de maio de 2007, para prorrogar o prazo de vigência da não incidência do Adicional aoFretepara Renovação da Marinha Mercante (AFRMM) previsto no art. 17 da Lei nº 9.432, de 8 de janeiro de 1997; a Lei nº 9.432, de 8 de janeiro de 1997; e a Lei nº 10.893, de 13 de julho de 2004.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('frete', '2025-07-12 17:36:02', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2018-05-27;831', 'MPV 831/2018', 'urn:lex:br:congresso.nacional:medida.provisoria;mpv:2018-05-27;831', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Congresso Nacional', '2018-05-27', NULL, 'Altera a Lei nº 8.029, de 12 de abril de 1990, que dispõe sobre a extinção e dissolução de entidades da administração pública federal.

