INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('frete', '2025-07-12 17:36:02', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.2:acordao;resp:2010-09-02;1057828-1050275', 'REsp 1057828 / SP', 'urn:lex:br:superior.tribunal.justica;turma.2:acordao;resp:2010-09-02;1057828-1050275', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Resp', '2010-09-02', 'ILEGALIDADE, APLICAÇÃO, SANÇÃO ADMINISTRATIVA, PELO, PROCON /
HIPÓTESE, ANÚNCIO PUBLICITÁRIO, VENDA, VEÍCULO AUTOMOTOR, SEM,
DISCRIMINAÇÃO, VALOR,FRETE; EXISTÊNCIA, APENAS, INFORMAÇÃO, NÃO,
INCLUSÃO, VALOR,FRETE, PREÇO, BEM / NÃO CARACTERIZAÇÃO, PUBLICIDADE
ENGANOSA; INVIABILIDADE, EXIGÊNCIA, DISCRIMINAÇÃO, VALOR,FRETE, EM,
ANÚNCIO PUBLICITÁRIO, ÂMBITO, TERRITÓRIO NACIONAL, MOTIVO,
EXISTÊNCIA, VARIAÇÃO, PREÇO, SERVIÇO; NÃO, OCORRÊNCIA, VIOLAÇÃO,
ARTIGO, CÓDIGO DE DEFESA DO CONSUMIDOR.', 'PROCESSUAL CIVIL E DIREITO DO CONSUMIDOR ? ANÚNCIO DE VEÍCULO  ?
VALOR DOFRETE? INFORMAÇÃO NO RODAPÉ ? LETRAS MIÚDAS ? REEXAME DE
PROVA ? ÓBICE DA SÚMULA 7/STJ ? PROPAGANDA ENGANOSA ?
NÃO-CARACTERIZAÇÃO.
1. Inviável a verificação do tamanho dos caracteres utilizados no
anúncio publicitário, em razão do óbice da Súmula 7/STJ.
2. Anúncio publicitário que informa a não-inclusão do valor dofreteno preço ofertado e, ao mesmo tempo, não especifica o seu valor
correspondente, por si só, não configura publicidade enganosa ou
abusiva, ainda que essa informação conste no rodapé do anúncio
veiculado em jornal.
3. Recurso especial não provido.
Decisão
Vistos, relatados e discutidos os autos em que são partes as acima
indicadas, acordam os Ministros da Segunda Turma do Superior
Tribunal de Justiça "Prosseguindo-se no julgamento, após o
voto-vista do Sr. Ministro Herman Benjamin, acompanhando a Sra.
Ministra Eliana Calmon, a Turma, por unanimidade, negou provimento
ao recurso, nos termos do voto da Sra. Ministra-Relatora, com a
ressalva do ponto de vista do Sr. Ministro Herman Benjamin." Os Srs.
Ministros Castro Meira, Humberto Martins, Herman Benjamin
(voto-vista) e Mauro Campbell Marques votaram com a Sra. Ministra
Relatora.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
