INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br;sao.paulo;mococa:municipal:lei:1974-06-24;1089', 'Lei n° 1089, de 24 de Junho de 1974', 'urn:lex:br;sao.paulo;mococa:municipal:lei:1974-06-24;1089', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Municipal', '1974-06-24', NULL, 'ABERTURA DE CRÉDITO ESPECIAL DE Cr$ 160.459,34 PARA O PAGAMENTO DO TERRENO ADQUIRIDO DO SR. DR. ALBERTO GARCIA DE FIGUEIREDO, COM A ÁREA DE 48.540,20m² A SER DOADO À FIRMA IRMÃOS NICOLA S/A. INDÚSTRIA  DE MÁQUINAS EIMPLEMENTOSRODOVIÁRIOS, PARA CONSTRUÇÃO DE IMÓVEIS E INSTALAÇÃO DE INDÚSTRIAS, ATRIBUIDO À SEGUINTE CATEGORIA ECONÔMICA E FUNÇÕES DE GOVERNO CONFORME LEI N° 4320/64.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2015-02-24;0000446-88.2014.5.03.0103', 'Acórdão TRT 3ª / Segunda Turma / 2015-02-24', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.2:acordao:2015-02-24;0000446-88.2014.5.03.0103', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2015-02-24', 'ESTABILIDADE SINDICAL - CABIMENTO', 'RECORRENTE(S): 	WILLIAN HENRIQUE DE ALMEIDA  RECORRIDO(S): 		MILIMPLEMENTOSPARA TRANSPORTES LTDA.  (1)  MEGATECNOLOGIAIMPLEMENTOSRODOVIARIOSLTDA. (2)    EMENTA: ESTABILIDADE PROVISÓRIA -REPRESENTAÇÃO SINDICAL - LIMITAÇÃO A SETE MEMBROS - ARTIGOS 522 E 543, 3º DA CLT E SÚMULA 369, II, DO TST. Determinam o art. 522 e o § 3º do art. 543, ambos da CLT, que a estabilidade provisória é assegurada apenas a sete membros eleitos para cargo na diretoria do sindicato, não se permitindo à referida entidade beneficiar-se com a garantia no emprego de diretores em número superior ao estipulado na lei. E, nos termos da Súmula 369, II, do TST, a restrição imposta pelo referido art. 522 foi recepcionada pela Constituição Federal; ou seja, o princípio constitucional da liberdade sindical, que veda a intervenção do Poder Público na organização dos sindicatos (art. 8º, I, da CF/88), não lhes outorga o direito de assegurarem estabilidade provisória para quantos cargos de direção lhes forem convenientes. Considerando que não existe prova de que o reclamante encontra-se inserido entre os 07 dirigentes sindicais ou os suplentes destes que usufruem da garantia de emprego, não há que se falar em estabilidade provisória, sendo válida a dispensa imotivada levada a efeito por sua empregadora.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.5:acordao;rr:2013-08-14;880-2011-662-9-0', 'Acórdão do processo Nº RR - 880-86.2011.5.09.0662', 'urn:lex:br:tribunal.superior.trabalho;turma.5:acordao;rr:2013-08-14;880-2011-662-9-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2013-08-14', NULL, 'RECURSO DE REVISTA ILEGITIMIDADE PARA RECORRER. NÃO CONHECIMENTO. Constata-se que, no presente caso, a ação foi ajuizada em face da empresa NORMA DO BRASIL S/A -, a qual compareceu em audiência, apresentou defesa e recurso ordinário. Não obstante, o recurso de revista foi interposto pela empresa - NORMA INDÚSTRIA E COMÉRCIO DEIMPLEMENTOSRODOVIÁRIOS- estranha à lide. Nesse contexto, impossível o conhecimento do recurso de revista interposto por pessoa jurídica diversa da reclamada, ante a ausência de legitimidade e de interesse recursal. Precedentes. Recurso de Revista não conhecido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.4:acordao;rr:2019-08-07;21259-2017-402-4-0', 'Acórdão do processo Nº RR - 21259-80.2017.5.04.0402', 'urn:lex:br:tribunal.superior.trabalho;turma.4:acordao;rr:2019-08-07;21259-2017-402-4-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2019-08-07', NULL, 'A) AGRAVO DE INSTRUMENTO EM RECURSO DE REVISTA INTERPOSTO PELA RECLAMADA MASSA FALIDA DE GUERRA S.A. -IMPLEMENTOSRODOVIÁRIOS. ACÓRDÃO REGIONAL PUBLICADO NA VIGÊNCIA DAS LEIS Nºs 13.015/2014 E 13.467/2017.  1. INDENIZAÇÃO POR DANO MORAL. ATRASO NO PAGAMENTO DE VERBAS RESCISÓRIAS. TRANSCENDÊNCIA POLÍTICA RECONHECIDA. CONHECIMENTO E PROVIMENTO. I. Hipótese em que a Corte Regional condenou a Reclamada ao pagamento de indenização por dano moral em razão do atraso no pagamento de verbas rescisórias, por entender que a configuração do referido dano se dá pela mera presunção de aborrecimento suportado pelo Reclamante. II. Demonstrada transcendência política da causa e violação do art. 5º, X, da Constituição da República. III. Agravo de instrumento de que se conhece e a que se dá provimento, para determinar o processamento do recurso de revista, observando-se o disposto na Resolução Administrativa nº 928/2003 do TST.  B) RECURSO DE REVISTA INTERPOSTO PELA RECLAMADA MASSA FALIDA DE GUERRA S.A. -IMPLEMENTOSRODOVIÁRIOS. ACÓRDÃO REGIONAL PUBLICADO NA VIGÊNCIA DAS LEIS Nos 13.015/2014 E 13.467/2017.  1. INDENIZAÇÃO POR DANO MORAL. ATRASO NO PAGAMENTO DE VERBAS RESCISÓRIAS. TRANSCENDÊNCIA POLÍTICA RECONHECIDA. CONHECIMENTO E PROVIMENTO. I. A jurisprudência desta Corte Superior está pacificada no sentido de que o dano moral não se presume no caso de descumprimento da obrigação do empregador de pagar a contraprestação devida ao empregado na época própria. O atraso no pagamento de verbas rescisórias não enseja o pagamento de indenização por danos morais, porque tal situação, isoladamente considerada, não importa resultado lesivo à honra ou à imagem das pessoas. Portanto, em tais hipóteses, é imprescindível a comprovação do dano à personalidade do trabalhador. II. Cabe ressaltar que o reconhecimento de que a causa oferece transcendência política (art. 896-A, § 1º, II, da CLT) não se limita à hipótese em que haja verbete sumular sobre a matéria; haverá igualmente transcendência política quando demonstrado o desrespeito à jurisprudência pacífica e notória do Tribunal Superior do Trabalho sedimentada em Orientação Jurisprudencial ou a partir da fixação de tese no julgamento, entre outros, de incidentes de resolução de recursos repetitivos ou de assunção de competência, bem como, na hipótese do Supremo Tribunal Federal, no julgamento de recurso extraordinário com repercussão geral ou das ações de constitucionalidade. Trata-se de extensão normativa do conceito de transcendência política, prevista no art. 896-A, § 1º, II, da CLT, a partir, sobretudo, da sua integração com o novo sistema de resolução de demandas repetitivas inaugurado pelo Código de Processo Civil de 2015, cujas decisões possuam caráter vinculante (exegese dos arts. 489, § 1º, 926, 928 do CPC/2015). Ademais, ainda que assim não fosse, o próprio § 1º do art. 896-A da CLT estabelece que os indicadores de transcendência nele nominados não constituem cláusula legal exaustiva, mas possibilita o reconhecimento de indicadores "entre outros". III. No presente caso, ao condenar a Reclamada ao pagamento de indenização por dano moral em razão do atraso no pagamento de verbas rescisórias, sem demonstrar a efetiva lesão aos direitos da personalidade do empregado, a Corte Regional divergiu da jurisprudência consolidada por esta Corte Superior e violou o art. 5º, X, da CF/88. Sob esse enfoque, impõe-se o conhecimento e provimento do recurso de revista. IV. Recurso de revista de que se conhece e a que se dá provimento.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.4:acordao;rr:2005-03-16;13400-1998-9-5-0', 'Acórdão do processo Nº RR - 13400-65.1998.5.05.0009', 'urn:lex:br:tribunal.superior.trabalho;turma.4:acordao;rr:2005-03-16;13400-1998-9-5-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2005-03-16', NULL, 'RECURSO DE REVISTA. PRELIMINAR DE INTEMPESTIVIDADE E DE DESERÇÃO ARGÜIDAS EM CONTRA-RAZÕES. Rejeita-se a denúncia do recorrido, de a revista interposta pela reclamada apresentar-se intempestiva em virtude de o recurso ordinário por ela ofertado não ter interrompido o prazo recursal. Isso porque o recurso ordinário difere dos embargos de declaração, que perdem o efeito interruptivo do art. 538 do CPC quando são interpostos intempestivamente ou tidos juridicamente como inexistentes. As razões veiculadas quanto à deserção da revista guardam pertinência com as que o foram pelo Regional para o não-conhecimento do recurso ordinário, motivo pelo qual me reporto aos fundamentos delineados no tópico relativo à questão. PRELIMINAR DE NULIDADE POR NEGATIVA DE PRESTAÇÃO JURISDICIONAL. Atento à evidência de estarem expressamente delineadas as premissas em que se ampararao Regional para dirimir a controvérsia suscitada em torno da deserção do recurso ordinário da reclamada, acha-se o Tribunal Superior em condições de levá-los em conta no exame da revista, com a amplitude desejada pelo recorrente. Recurso não conhecido. RECURSO ORDINÁRIO NÃO CONHECIDO POR DESERÇÃO. AUSÊNCIA DE CONDENAÇÃO EM PECÚNIA. DEPÓSITO RECURSAL. DESNECESSIDADE. Constata-se ter sido julgado extinto, em primeira instância, sem julgamento do mérito, o processo relativamente à ação incidente de exibição de documentos, formulada pela empresa-reclamada contra a RodometalImplementosRodoviários, nos termos do artigo 267, IV, do CPC, invocando aquele juízo, para tanto, a incompetência ratione materiae. Disso resulta que não houve condenação em pecúnia, sendo inexigível o depósito recursal, a teor do Enunciado nº 161/TST. Recurso provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:1998-12-09;430722-1998-5555-15-0', 'Acórdão do processo Nº AIRR - 430722-03.1998.5.15.5555', 'urn:lex:br:tribunal.superior.trabalho;turma.3:acordao;airr:1998-12-09;430722-1998-5555-15-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Airr', '1998-12-09', NULL, 'AGRAVO DE INSTRUMENTO. RECURSO DE REVISTA. EXAME DE PROVA. Não tem cabimento o recurso de revista quando o seu desiderato conduz ao reexame do conjunto fático-probatório, incidindo o Enunciado 126/TST.    Vistos, relatados e discutidos estes autos de Agravo de Instrumento em Recurso de Revista nº TST-AIRR-430.722/98.0, em que é Agravante MOGI MIRIMIMPLEMENTOSRODOVIÁRIOSE AGRÍCOLAS INDÚSTRIA E COMÉRCIO LTDA e Agravado FAUSTO APARECIDO BARBANTE.    Contra a r. decisão da ilustrada vice-Presidência do Eg. 15º Regional, que denegou seguimento a seu recurso de revista por entender não configurada a negativa de prestação jurisdicional e incidente o Enunciado 126 desta Corte (fls. 74), o reclamado interpôs agravo de instrumento sustentado haver demonstrado o cabimento daquele recurso por ter o acórdão regional violado literal dispositivo de lei federal, ofendido preceito constitucional e estabelecido divergência jurisprudencial com os arestos que colacionou (fls. 03/04).     Sem contraminuta,  a d. Procuradoria Geral do Trabalho não se manifestou nos autos, uma vez não evidenciadas as hipóteses da sua intervenção obrigatória, nos termos do artigo 113, do Regimento Interno do Tribunal Superior do Trabalho.  É o relatório.    V O T OI - ADMISSIBILIDADEAgravo tempestivo, devidamente instrumentado e regularmente processado, dele conheço.    II. MÉRITOO Egrégio Tribunal Regional, através do v. acórdão de fls. 38/40 e da decisão de fls. 45/47, que julgou os embargos de declaração, negou provimento ao recurso ordinário do reclamado e manteve o reconhecimento do vínculo empregatício e seus consectários.    Inconformado, o reclamado interpôs recurso de revista (fls. 48/53) sustentando que o acórdão regional violou os artigos 5º, inciso XXXV, da Constituição Federal 2º, caput, 3º e 832 da CLT e 458, inciso II, do CPC e estabeleceu divergência jurisprudencial com os arestos colacionados.    A negativa de prestação jurisdicional não existiu.    O acórdão de fls. 38/40 examinou toda matéria versada na lide, oferecendo a fundamentação devida.    Nos embargos, à guisa de omissão e de obscuridade, pretendeu-se a reapreciação de determinados pontos, o que foi repelido, posto já oferecida, em relação a eles, a satisfatória prestação jurisdicional, com os motivos claros da formação do convencimento do Órgão julgador.     Não se vislumbram violados, portanto, os preceitos constitucional e legais indigitados pelo agravante (artigos 5º, inciso XXXV, da Constituição Federal, 832 da CLT e 458, inciso II, do CPC).    Os arestos colacionados, à luz da fundamentação contida na decisão hostilizada, revelam-se inespecíficos.    No tocante ao reconhecimento da relação de emprego, a decisão regional tem o seguinte teor, verbis:     "O reclamante nunca deixou de trabalhar como empregado, não tendo ficado provada a alegação da defesa de ter o mesmo, após a vigência do segundo contrato, de não cumprir qualquer horário"  (fl. 39).    A questão, portanto, acha-se vinculada ao contexto fático-probatório, cujo reexame é obstado nesta fase recursal pelo Enunciado 126 desta Corte.    Inexiste, portanto, matéria de direito a reclamar revisão, restando não violados os artigo 2º, "caput", e 3º da CLT.  Nego provimento.     ISTO POSTOACORDAM os Ministros da Terceira Turma do Tribunal Superior do Trabalho, unanimemente, em negar provimentoao agravo.   Brasília, 09 de dezembro de 1998.        M inistro JOSÉ LUIZ VASCONCELLOSPresidenteJ uiz C onvocado TARCÍSIO ALBERTO GIBOSKIRelator', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.3:acordao;resp:2008-06-17;931556-854523', 'REsp 931556 / RS', 'urn:lex:br:superior.tribunal.justica;turma.3:acordao;resp:2008-06-17;931556-854523', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Resp', '2008-06-17', NULL, 'RESPONSABILIDADE CIVIL. ACIDENTE DO TRABALHO. MORTE. INDENIZAÇÃO POR
DANO MORAL. FILHO NASCITURO. FIXAÇÃO DO QUANTUM INDENIZATÓRIO. DIES
A QUO. CORREÇÃO MONETÁRIA. DATA DA FIXAÇÃO PELO JUIZ. JUROS DE MORA.
DATA DO EVENTO DANOSO.
PROCESSO CIVIL. JUNTADA DE DOCUMENTO NA FASE RECURSAL.
POSSIBILIDADE, DESDE QUE NÃO CONFIGURADA A MÁ-FÉ DA PARTE E
OPORTUNIZADO O CONTRADITÓRIO. ANULAÇÃO DO PROCESSO. INEXISTÊNCIA DE
DANO. DESNECESSIDADE.
- Impossível admitir-se a redução do valor fixado a título de
compensação por danos morais em relação ao nascituro, em comparação
com outros filhos do de cujus, já nascidos na ocasião do evento
morte, porquanto o fundamento da compensação é a existência de um
sofrimento impossível de ser quantificado com precisão.
- Embora sejam muitos os fatores a considerar para a fixação da
satisfação compensatória por danos morais, é principalmente com base
na gravidade da lesão que o juiz fixa o valor da reparação.
- É devida correção monetária sobre o valor da indenização por dano
moral fixado a partir da data do arbitramento. Precedentes.
- Os juros moratórios, em se tratando de acidente de trabalho, estão
sujeitos ao regime da responsabilidade extracontratual,
aplicando-se, portanto, a Súmula nº 54 da Corte, contabilizando-os a
partir da data do evento danoso. Precedentes
- É possível a apresentação de provas documentais na apelação, desde
que não fique configurada a má-fé da parte e seja observado o
contraditório. Precedentes.
- A sistemática do processo civil é regida pelo princípio da
instrumentalidade das formas, devendo ser reputados válidos os atos
que cumpram a sua finalidade essencial, sem que acarretem prejuízos
aos litigantes.
Recurso especial dos autores parcialmente conhecido e, nesta parte,
provido. Recurso especial da ré não conhecido.
Decisão
Vistos, relatados e discutidos estes autos, acordam os Ministros da
TERCEIRA TURMA do Superior Tribunal de Justiça, na conformidade dos
votos e das notas taquigráficas constantes dos autos, prosseguindo
no julgamento, após o voto do Sr. Ministro Sidnei Beneti,  por
unanimidade, conhecer do recurso especial de Luciana Maria Bueno
Rodrigues e Outros e dar-lhe provimento, e não conhecer do recurso
especial interposto por Rodocar SulImplementosRodoviáriosLTDA,
nos termos do voto da Sra. Ministra Relatora. Os Srs. Ministros
Massami Uyeda, Sidnei Beneti e Ari Pargendler votaram com a Sra.
Ministra Relatora.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.2:acordao;resp:2021-10-05;1925025-2101591', 'REsp 1925025 / SC', 'urn:lex:br:superior.tribunal.justica;turma.2:acordao;resp:2021-10-05;1925025-2101591', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Resp', '2021-10-05', '"[...] a limitação de compensação prevista nos arts. 42 e 58,
da Lei n. 8.981/95, e nos arts. 15 e 16, da Lei n. 9.065/95, não tem
por pressuposto a continuidade da pessoa jurídica. Para as normas é
indiferente se as pessoas jurídicas irão ou não ser extintas, isso
em nada afeta a sua incidência. Não há nada na letra da lei que leve
a este raciocínio".', 'PROCESSUAL CIVIL. TRIBUTÁRIO. IMPOSTO DE RENDA DA PESSOA JURÍDICA -
IRPJ. CONTRIBUIÇÃO SOCIAL SOBRE O LUCRO LÍQUIDO - CSLL. COMPENSAÇÃO
DE PREJUÍZO FISCAL E BASE DE CÁLCULO NEGATIVA. APLICAÇÃO DOS LIMITES
DE 30%, DOS ARTS. 15 E 16, DA LEI N. 9.065/95 E ARTS. 42 E 58, DA
LEI N. 8.981/95 TAMBÉM PARA EMPRESAS EXTINTAS (INCORPORAÇÃO, FUSÃO,
CISÃO) SOB PENA DE VIOLAÇÃO INDIRETA (FRAUDE À LEI) AO ART. 33, DO
DECRETO-LEI N. 2.341/87.
1. A empresa contribuinte, ciente da regra jurídica cogente
proibitiva consistente na vedação da utilização dos prejuízos
fiscais prevista no art. 33, do Decreto-Lei n. 2.341/87 ("art. 33. A
pessoa jurídica sucessora por incorporação, fusão ou cisão não
poderá compensar prejuízos fiscais da sucedida"), objetiva
provimento declaratório para o aproveitamento integral dos prejuízos
fiscais de IRPJ e bases negativas de CSLL, afastando-se os efeitos
dos art. 42 e 58 da Lei 8.981/95, com redação dada pela Lei nº
9.065/95, quando de sua futura extinção (por incorporação, fusão ou
cisão).
2. Na prática, pleiteia-se que a empresa futuramente sucessora (por
incorporação, fusão ou cisão), também ciente da regra jurídica
cogente proibitiva consistente na vedação da utilização dos
prejuízos fiscais prevista no art. 33, do Decreto-Lei n. 2.341/87,
possa contornar essa regra ao fazer uso de 100% desses prejuízos
fiscais dentro da própria incorporada, fusionada ou cindida antes de
a incorporar, fundir-se a ela ou cindir (assim o faria sem dívidas
tributárias), afastando ali a limitação de 30%, dos arts. 15 e 16,
da Lei n. 9.065/95 e arts. 42 e 58, da Lei n. 8.981/95, ao argumento
de que a "vedação de 30% estabelecida na Lei n. 8.981/95 somente
faria sentido para as empresas que estão continuando a sua atividade
e não para aquelas que estão se extinguindo". Nessas condições, a
empresa futuramente sucessora estaria fazendo uso do prejuízo fiscal
da sucedida a ser futuramente extinta (na própria sucedida e, por
conseguinte, também em si mesma na condição de sucessora, já que ou
eram ou se tornarão uma única empresa) para além do limite legal
previsto.
3. A ótica reconhecida por ambas as Turmas desta Corte foi a de que
o procedimento é uma burla ao art. 33, do Decreto-Lei n. 2.341/87
através do afastamento da Lei n. 8.981/95, caracterizando violação
indireta à lei (fraude à lei). Precedentes: REsp. n. 1.805.925 - SP,
Primeira Turma, Rel. Min. Napoleão Nunes Maia Filho, Rel. p/ acórdão
Min. Gurgel de Faria, DJe 5/8/2020; EDcl nos EDcl no AgInt nos EDcl
no REsp. n. 1.725.911 - SP, Segunda Turma, Rel. Min. Herman
Benjamin, julgado em 16.11.2020; REsp. n. 1.107.518 - SC, Segunda
Turma, Rel. Min. Eliana Calmon, julgado em 06.08.2009.
4. O conjunto normativo composto pelas limitações constantes do art.
33, do Decreto-Lei n. 2.341/87; arts. 15 e 16, da Lei n. 9.065/95 e
arts. 42 e 58, da Lei n. 8.981/95; deve ser interpretado à luz da
cláusula antielisiva específica do art. 51, da Lei n. 7.450/85,
dispositivo legal que já teve aplicação reconhecida no REsp. n.
1.743.918 / SP, Segunda Turma, Rel. Min. Mauro Campbell Marques,
julgado em 19.03.2019.
5. O conjunto produz norma antielisiva para reduzir os incentivos a
que as empresas passem a fabricar prejuízos fiscais a fim de serem
adquiridos no mercado mediante incorporação por outras (normalmente
estando todas sob mesma orientação dentro de um grupo econômico de
fato ou mesma consultoria tributária) com o propósito único de
reduzir o IRPJ e a CSLL devidos (ausência de propósito negocial).
Trata-se de um típico caso onde a empresa que assim procede busca a
chancela do Poder Judiciário para realizar um Planejamento
Tributário Abusivo. A compreensão do tema já havia sido feita no
REsp. n. 1.107.518/SC (Segunda Turma, Rel. Min. Eliana Calmon,
julgado em 06.08.2009), como bem observado no acórdão embargado.
6. Recurso especial não provido.
Decis?o
Vistos, relatados e discutidos esses autos em que são partes as
acima indicadas, acordam os Ministros da SEGUNDA TURMA do Superior
Tribunal de Justiça, na conformidade dos votos e das notas
taquigráficas, o seguinte resultado de julgamento:
"A Turma, por unanimidade, negou provimento ao recurso, nos termos
do voto do Sr. Ministro Relator."
A Sra. Ministra Assusete Magalhães, os Srs. Ministros Francisco
Falcão, Herman Benjamin e Og Fernandes votaram com o Sr. Ministro
Relator.

SUSTENTAÇÃO ORAL

Dr(a). CARLOS EDUARDO DOMINGUES AMORIM, pela parte RECORRENTE:
LIBRELATO S.A.IMPLEMENTOSRODOVIARIOS', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;rr:2017-03-29;53800-2012-14-17-0', 'Acórdão do processo Nº RR - 53800-82.2012.5.17.0014', 'urn:lex:br:tribunal.superior.trabalho;turma.7:acordao;rr:2017-03-29;53800-2012-14-17-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2017-03-29', NULL, 'RECURSO DE REVISTA - RECURSO INTERPOSTO SOB A ÉGIDE DO CPC/73 E ANTERIORMENTE À VIGÊNCIA DA LEI Nº 13.015/2014 -  ECT -  CONTRATO TEMPORÁRIO -  TERCEIRIZAÇÃO -  TRANSPORTERODOVIÁRIO. A atividade de transporte de carga entre agências da reclamada não pode ser concebida como atividade-fim da empresa, na medida em que exercida apenas como forma de viabilizar a logística de entrega das correspondências e mercadorias ao seu destino, essa sim, consistente na atividade postal propriamente dita (art. 7º, da Lei nº 6.538/78). Tanto assim o é que o Decreto nº 2.271/97, que trata da contratação de serviços pela Administração Pública Federal, autoriza a execução indireta das atividades de transporte. Cabe, ainda, o registro de que a Empresa Brasileira de Correios e Telégrafos por força da edição recente da Lei nº 12.490/2011, passou a ter autorização para constituir subsidiárias e/ou adquirir participação acionária em outras empresas para a execução de atividades compreendidas em seu objeto, sendo relevante citar que no próprio dispositivo legal autorizador existe uma única limitação acerca da atuação das empresas que vierem a ser constituídas ou adquiridas pelos Correios, qual seja a vedação de operarem o serviço de entrega domiciliar. Portanto, a alteração substancial do contexto no qual opera a Empresa Brasileira de Correios e Telégrafos ensejou oimplementode alternativas viáveis à manutenção das suas operações, considerada a vastidão continental na qual atua. E dessa alteração legislativa redunda a possibilidade de contratação de serviços por empresas outras, ainda que delas seja a ECT proprietária ou acionista, para a atuação em suas atividades, repetindo-se o óbice apenas para o serviço de entrega domiciliar por força do monopólio postal. Assim, deve-se inclusive alertar para o aspecto de que há muito se utiliza a ECT de contratação de transportes aéreos para a distribuição entre suas centrais nas diversas cidades, sem que disso resulte situação de ilicitude no que se refere a terceirização. Ou seja, autorizada e lícita a terceirização para um modal de transporte, nada justifica a conclusão diversa para o modalrodoviário. Recurso de revista conhecido e provido.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2025-02-03;0010600-45.2023.5.03.0041', 'Acórdão PJe TRT 3ª / Primeira Turma / 2025-02-03', 'urn:lex:br;justica.trabalho;regiao.3:tribunal.regional.trabalho;turma.1:acordao:2025-02-03;0010600-45.2023.5.03.0041', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 3', 'Tribunal Regional Trabalho', 'Acordao', '2025-02-03', 'TRABALHADOR RURAL - ENQUADRAMENTO SINDICAL', 'ENQUADRAMENTO SINDICAL - "Como cediço, o enquadramento sindical se dá pela atividade preponderante do empregador (art. 570 da CLT), excepcionada a hipótese de categoria profissional diferenciada, sempre dentro dos limites territoriais dos sindicatos, garantindo aos empregados a plena incidência a seus contratos de trabalho das condições e benefícios estipulados em instrumentos coletivos abrangendo a base territorial mínima do art. 8º, II, da Constituição da República. In casu, o contrato social da primeira reclamada aponta como objetivo social "o transporterodoviáriode cargas municipal, intermunicipal, interestadual e internacional; serviços de pulverização e controle de pragas agrícolas; serviços de preparação do terreno, cultivo e colheita; aluguel de máquinas e equipamentos agrícolas sem operador; locação de caminhões, reboques, semirreboques, máquinas agrícolas,implementosagrícolas e similares." (ID. 157d7ea), atividades que estão em consonância com o CNAE de ID. 214f537. A seu turno, o contrato firmado entre as reclamadas diz respeito a serviços de transporterodoviáriode cana-de-açúcar entre as áreas de lavoura e os estabelecimentos industriais da terceira reclamada (lD. c3f45b2 e seguintes), enquadrando-as, portanto, como empregadoras rurais, nos termos do artigo 3º da Lei 5.889/1973. Embora contratado pela primeira reclamada, o reclamante trabalhou exclusivamente em favor da terceira reclamada, empresa pertencente à agroindústria, estando suas atividades inseridas na sua dinâmica de produção de açúcar e álcool, o que atrai o enquadramento como empregado motorista rural, conforme artigo 2º da Lei 5889/1973. A corroborar, o reclamante possuía a jornada de trabalho registrada tal como qualquer outro empregado da reclamada, exercente de funções administrativas ou da parte operacional propriamente dita (lidando diretamente com plantio, colheita e atividades fins)." ( Fragmento da sentença da lavra da MM. Juíza Vaneli Cristine Silva de Mattos).', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.5:acordao;hc:2021-04-06;635509-2040925', 'HC 635509 / SP', 'urn:lex:br:superior.tribunal.justica;turma.5:acordao;hc:2021-04-06;635509-2040925', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Hc', '2021-04-06', NULL, 'HABEAS CORPUS SUBSTITUTIVO DE RECURSO PRÓPRIO. NÃO CABIMENTO.
INTEGRAR ORGANIZAÇÃO CRIMINOSA. CORRUPÇÃO ATIVA E PASSIVA.
FALSIFICAÇÃO DE DOCUMENTO PÚBLICO E PARTICULAR. AUSÊNCIA DE INDÍCIOS
SUFICIENTES DE AUTORIA E PROVA DA MATERIALIDADE DELITIVA.
REVOLVIMENTO FÁTICO-PROBATÓRIO. IMPOSSIBILIDADE DE ANÁLISE NA
PRESENTE VIA. PRISÃO PREVENTIVA. FUNDAMENTAÇÃO IDÔNEA.
PERICULOSIDADE DA AGENTE. MODUS OPERANDI. FRAUDE NAS NORMAS DE
TRÂNSITO. FUNDADO RECEIO DE REITERAÇÃO DELITIVA. NECESSIDADE DE
CONTENÇÃO DO GRUPO CRIMINOSO. GARANTIA DA ORDEM PÚBLICA.
IRRELEVÂNCIA DAS CONDIÇÕES PESSOAIS FAVORÁVEIS QUANDO PRESENTES OS
REQUISITOS DA CAUTELA. INAPLICABILIDADE DE MEDIDA CAUTELAR
ALTERNATIVA. INSUFICIÊNCIA. RISCO DE CONTAMINAÇÃO PELA COVID-19.
RECOMENDAÇÃO N. 62 DO CONSELHO NACIONAL DE JUSTIÇA ? CNJ. RÉU NÃO
COMPROVOU ESTAR INSERIDO NO GRUPO DE RISCO. PROPORCIONALIDADE ENTRE
A MEDIDA CAUTELAR E PENA PROVÁVEL. INVIABILIDADE DE EXAME NA VIA
ELEITA. CONSTRANGIMENTO ILEGAL NÃO EVIDENCIADO. HABEAS CORPUS NÃO
CONHECIDO.
1. Diante da hipótese de habeas corpus substitutivo de recurso
próprio, a impetração não deve ser conhecida, segundo orientação
jurisprudencial do Supremo Tribunal Federal ? STF e do próprio
Superior Tribunal de Justiça ? STJ. Contudo, considerando as
alegações expostas na inicial, razoável a análise do feito para
verificar a existência de eventual constrangimento ilegal.
2. Em razão da exigência de revolvimento do conteúdo
fático-probatório, a estreita via do habeas corpus, bem como do
recurso ordinário em habeas corpus, não é adequada para a análise
das teses de negativa de autoria e da existência de prova robusta da
materialidade delitiva.
3. O decreto preventivo, confirmado pelo Tribunal de origem,
descreveu, ainda que de forma sucinta, as condutas imputadas ao
paciente, delimitando a sua função dentro da organização criminosa.
Nesse contexto, cumpre destacar que a jurisprudência desta Superior
Corte de Justiça firmou o entendimento de que em delito de autoria
coletiva a necessidade de minuciosa individualização da conduta de
cada acusado é mitigada diante da complexidade do caso, bastando que
haja descrição fática suficiente a demonstrar a existência do crime
e o vínculo entre o acusado e a empreitada criminosa, o que ocorreu
no caso concreto (RHC 42.294/MG, Rei. Ministra MARIA THEREZA DE
ASSIS MOURA, SEXTA TURMA, DJe 05/05/2014).
4. Em vista da natureza excepcional da prisão preventiva, somente se
verifica a possibilidade da sua imposição quando evidenciado, de
forma fundamentada e com base em dados concretos, o preenchimento
dos pressupostos e requisitos previstos no art. 312 do Código de
Processo Penal ? CPP. Deve, ainda, ser mantida a prisão antecipada
apenas quando não for possível a aplicação de medida cautelar
diversa, nos termos previstos no art. 319 do CPP.
No caso, a prisão preventiva foi adequadamente motivada, tendo sido
demonstrada pelas instâncias ordinárias, com base em elementos
extraídos dos autos, a periculosidade do paciente, evidenciada pelo
fato de ser integrante de organização criminosa bem estruturada, com
divisão de tarefas, inclusive com participação de funcionários
públicos do Detran, voltada para a prática de diversos crimes, em
especial delitos de falsidade, inserção de dados falsos em sistema
público de informações, corrupção ativa, corrupção passiva e lavagem
de capitais. Das investigações foi verificado que, em relação ao
paciente, na qualidade de proprietário da empresa Idali CarretasImplementosRodoviários, seria um dos responsáveis por providenciar
a instalação do 4º eixo complementar em inúmeros veículos
semirreboques, provenientes de diversas localidades, de modo a
proporcionar maior capacidade de carga, prática não admitida pelas
normas de trânsito, recomendando-se, assim, a sua custódia cautelar
para garantia da ordem pública, para assegurar a aplicação da lei
penal, e, principalmente, com o intuito de impedir a reiteração
delitiva por parte dos integrantes de organizações criminosas.
 5. É entendimento do Superior Tribunal de Justiça ? STJ que as
condições favoráveis do agente, por si sós, não impedem a manutenção
da prisão cautelar quando devidamente fundamentada.
6. Inaplicável medida cautelar alternativa quando as circunstâncias
evidenciam que as providências menos gravosas seriam insuficientes
para a manutenção da ordem pública.
7. O risco trazido pela propagação da COVID-19 não é fundamento
hábil a autorizar a revogação automática de toda custódia cautelar,
sendo imprescindível, para tanto, que haja comprovação de que o réu
encontra-se inserido na parcela mais suscetível à infecção, bem
como, que haja possibilidade da substituição da prisão preventiva
imposta. No caso, o paciente não comprovou que está inserido no
grupo de risco ou que necessite atualmente de assistência à saúde
não oferecida pela penitenciária, não se encontrando, portanto, nas
hipóteses previstas pela Recomendação do CNJ, não havendo se falar
em revogação da prisão preventiva ou sua substituição por prisão
domiciliar em razão da pandemia.
Além do mais, ressaltou a Corte Paulista que o Secretário da
Administração Penitenciária informou que tem tomado todas as medidas
necessárias à prevenção do vírus nos estabelecimentos penais,
destacando a reposição de insumos de limpeza e higiene, a
distribuição de mais de 70 mil máscaras reutilizáveis aos
custodiados, prioritariamente nos presídios com elevado índice de
suspeita de infecção. Anotou ainda que em 154 unidades há, ao menos,
um profissional de saúde pertencente aos quadros da Secretaria da
Administração Penitenciária, para o pronto atendimento, além das
equipes médicas que atendem 59 unidades e que, na ausência de equipe
de saúde, o custodiado poderá ser atendido na rede pública local;
sem falar nas medidas restritivas de visitação, atividades externas,
assistências internas, redução de movimentações, que têm por
objetivo minimizar a possibilidade de contágio entre custodiados e
população em geral.
8. Inexiste ofensa ao princípio da proporcionalidade entre a
custódia cautelar e eventual condenação que o recorrente
experimentará, pois referida análise deve ficar sujeita ao Juízo de
origem, que realizará cognição exauriente dos fatos e provas
apresentados no caso concreto. Não sendo possível, assim, concluir,
na via eleita, a quantidade de pena que poderá ser imposta, menos
ainda se iniciará o cumprimento da reprimenda em regime diverso do
fechado.
9. Habeas corpus não conhecido.
Decis?o
Vistos e relatados estes autos em que são partes as acima indicadas,
acordam os Ministros da QUINTA TURMA do Superior Tribunal de
Justiça, por unanimidade, não conhecer do pedido.
Os Srs. Ministros Felix Fischer, João Otávio de Noronha, Reynaldo
Soares da Fonseca e Ribeiro Dantas votaram com o Sr. Ministro
Relator.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.7:acordao:2010-08-05;00732001320065010055', 'ACÓRDÃO TRT 1ª  / 7ª Turma / 0073200-13.2006.5.01.0055 - DOERJ 05-08-2010', 'urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.7:acordao:2010-08-05;00732001320065010055', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 1', 'Tribunal Regional Trabalho', 'Acordao', '2010-08-05', NULL, 'RODOVIÁRIOS- INTERVALO INTRAJORNADA - SUPRESSÃO OU FRACIONAMENTO
A norma que regula o descanso possui caráter imperativo, ou seja, é de ordem pública e constitui-se em garantia mínima assegurada aos trabalhadores.  Portanto, inconcebível a pretendida substituição da norma, que obriga a concessão do intervalos, por cláusula que estabelece fracionamento ou supressão do intervalo intrajornada.
Tratando-se de normas de ordem pública, o diploma consolidado estabelece o mínimo, sendo que o sistema de proteção ao trabalho subordinado busca, calcado em sua base de princípios, oimplementode condições sempre mais vantajosas, seja por meio da função legiferante do Estado, seja por meio de negociação individual ou coletiva.
Ampara nosso entendimento a Orientação Jurisprudencial  342 da Seção de Dissídios Individuais-I do Colendo Tribunal Superior do Trabalho.
A questão aqui sub oculis não passa apenas pela necessária preservação da saúde do obreiro.  Não se pode perder de vista que transporte coletivo é serviço público e que a supressão do intervalo mínimo põe em risco toda a população que transita nas ruas.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br:tribunal.superior.trabalho;turma.4:acordao;rr:2019-03-13;10287-2014-44-15-0', 'Acórdão do processo Nº RR - 10287-57.2014.5.15.0044', 'urn:lex:br:tribunal.superior.trabalho;turma.4:acordao;rr:2019-03-13;10287-2014-44-15-0', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Tribunal Superior Trabalho', 'Acordao;Rr', '2019-03-13', NULL, 'AGRAVO. ENQUADRAMENTO SINDICAL. MOTORISTAS, TRATORISTAS E OPERADORES DE MÁQUINAS. CATEGORIA PROFISSIONAL DIFERENCIADA. ATIVIDADE PREPONDERANTEMENTE RURAL. PROVIMENTO. Ante o equívoco no exame do agravo de instrumento, dá-se provimento ao agravo. Agravo a que se dá provimento.  AGRAVO DE INSTRUMENTO. ENQUADRAMENTO SINDICAL. MOTORISTAS, TRATORISTAS E OPERADORES DE MÁQUINAS. CATEGORIA PROFISSIONAL DIFERENCIADA. ATIVIDADE PREPONDERANTEMENTE RURAL. PROVIMENTO. Ante a possível violação do artigo § 3º do artigo 511 da CLT, o provimento do agravo de instrumento para o exame do recurso de revista é medida que se impõe. Agravo de instrumento a que se dá provimento.  RECURSO DE REVISTA ENQUADRAMENTO SINDICAL. MOTORISTAS, TRATORISTAS E OPERADORES DE MÁQUINAS. CATEGORIA PROFISSIONAL DIFERENCIADA. ATIVIDADE PREPONDERANTEMENTE RURAL. PROVIMENTO. Cinge-se a controvérsia em definir o sindicato representativo da categoria dos motoristas, tratoristas e operadores de máquinas que prestam serviços para empresa que exerce preponderantemente atividade rural. A Constituição Federal, em seu artigo 8º, II, consagra o princípio da unicidade sindical, segundo o qual é vedada a coexistência de mais de um sindicato representativo dos direitos de determinada categoria, seja ela profissional ou econômica, em uma mesma base territorial.  É possível extrair desse dispositivo constitucional, como bem pontuado por Rodolfo Pamplona et al, que a categoria funciona como uma espécie de "liame que molda todo o sindicalismo brasileiro" (PAMPLONA FILHO, Rodolfo et al. Pluralidade sindical e democracia, p. 116. 2ª edição. São Paulo: LTr, 2013), de modo que a associação em um determinado sindicato deve ter esse elemento como referência. A definição de categoria econômica e profissional, para fins de enquadramento sindical, encontra-se inserida nos §§ 1º e 2º do artigo 511 da CLT, respectivamente. Com efeito, segundo o § 2º do artigo 511 da CLT, a "similitude de condições de vida oriunda da profissão ou trabalho em comum, em situação de emprego na mesma atividade econômica ou em atividades econômicas similares ou conexas, compõe a expressão social elementar compreendida como categoria profissional". Verifica-se que a categoria profissional é definida de acordo com a atividade econômica do empregador, a partir da qual é presumida a homogeneidade e a solidariedade de interesses dos trabalhadores, sendo irrelevante a formação do empregado, tampouco a profissão por ele exercida. É cediço, contudo, que a CLT prevê ainda a existência de uma terceira categoria para fins de enquadramento sindical, formada por "empregados que exerçam profissões ou funções diferenciadas por força de estatuto profissional especial ou em consequência de condições de vida singulares" (artigo 511, § 3º, da CLT).  Trata-se da categoria profissional diferenciada, na qual deve ser considerada a atividade profissional desempenhada pelo trabalhador, diferenciada a partir da existência de legislação própria que a discipline ou da singularidade das condições de vida. Diferentemente da categoria profissional, essa independe da atividade econômica do empregador. O legislador entendeu que, em razão de algumas profissões possuírem determinadas particularidades que as distinguem das demais, a despeito de os trabalhadores prestarem serviços para um mesmo empregador, necessitam de sindicato próprio para representar os seus interesses. No caso em exame, conforme consignado no acórdão regional, a autora tem como objeto social o "Serviço de preparação de terreno, cultivo e colheita de cana de açúcar; transporterodoviáriode cargas, exceto produtos perigosos e mudança intermunicipal, interestadual e internacional; aluguel deimplementosagrícolas". Reconheceu-se, por essa razão, que a atividade preponderante, por ela exercida, é a rural. Conforme anteriormente salientado, a priori, a definição do ente sindical representativo dos interesses dos trabalhadores é feita a partir da atividade econômica preponderante do empregador. Em se tratando de empregadora que exerça atividade preponderantemente rural, esta colenda Corte Superior, nos julgados em que o objeto de discussão era o enquadramento sindical dos trabalhadores, aplicava o entendimento consubstanciado nas Orientações Jurisprudenciais nos 315 e 419 da SBDI-1, atualmente canceladas, as quais preconizavam que seriam considerados trabalhadores rurais aqueles que prestam serviço a empregador que possua atividade preponderantemente rural. No que concerne à Orientação Jurisprudencial nº 315 da SBDI-1, decidiu-se pelo seu cancelamento em razão de a atividade de motorista possuir estatuto profissional próprio (Leis nos 12.619/2012 e 13.103/2015), motivo pelo qual, à luz do § 3º do artigo 511 da CLT, o seu enquadramento sindical independeria da atividade econômica desempenhada pelo empregador, por se tratar de categoria profissional diferenciada. Interessante ressaltar que o posicionamento cristalizado no referido verbete jurisprudencial, editado no ano de 2003, adveio de reiterados julgados que equiparavam os motoristas de empresas, cuja atividade era preponderantemente rural, aos trabalhadores rurais para fins de prescrição, uma vez que, até o ano 2000 (quando foi promulgada a Emenda Constitucional nº 28), o prazo prescricional aplicado para trabalhadores urbanos e rurais era distinto. A orientação jurisprudencial em referência, portanto, originou-se do julgamento de ações propostas antes de maio de 2000, quando ainda vigente o artigo 233 da Constituição Federal de 1988, que disciplinava a prescrição aplicável ao trabalhador rural, posteriormente revogado pela Emenda Constitucional nº 28/2000.  Ocorre que, a despeito da temática abordada em seus precedentes, a redação da orientação jurisprudencial em foco adentrou a esfera do enquadramento sindical, embora esse não tivesse sido, especificamente, o objeto da discussão. Isso porque a inserção do termo "enquadramento" à redação da Orientação Jurisprudencial nº 315 gerou dúvidas quanto à sua interpretação, no que diz respeito à correta representação sindical dos motoristas que se ativavam no âmbito de empresas rurais. O que acontecia, na prática, é que o posicionamento consolidado no Tribunal Superior do Trabalho induzia à modificação do enquadramento sindical dessa classe de motoristas, que deixavam de integrar categoria diferenciada e tornavam-se, pois, efetivos rurícolas.  Em consequência, a representação sindical era feita por organizações sindicais rurais que não guardavam qualquer identidade com a categoria, comprometendo, assim, a efetividade das negociações coletivas e a conquista dos direitos. Com o cancelamento das Orientações Jurisprudenciais nos 315 e 419 da SBDI-1, o posicionamento desta colenda Corte foi alterado, de modo que, para fins de definição do sindicato representativo dos trabalhadores que prestam serviço para empresas cuja atividade preponderante seja rural, passou-se a entender pela necessidade de ser observado se esses pertencem a alguma categoria profissional diferenciada, como a de motorista. Cumpre destacar que o egrégio Tribunal Regional, no caso em exame, reconheceu que os trabalhadores da autora -- motoristas, tratoristas e operadores de máquinas em geral que laboram nas empresas agrícolas -- não se inseriam na previsão contida na Lei nº 12.619/2012, seguida pela Lei nº 13.103/2015, por entender que os referidos diplomas legais regulam apenas os motoristas que exercem suas atividades junto ao transporterodoviáriode passageiros e de cargas. É bem verdade que, tanto o artigo 1º da Lei nº 12.619/2012, atualmente revogado, quanto o parágrafo único do artigo 1º da Lei nº 13.103/2015, estabelecem que os motoristas de veículos automotores cuja condução exija formação profissional e que exerçam a profissão nas atividades ou categorias econômicas de transporterodoviáriode passageiros e de transporterodoviáriode cargas integram a categoria profissional disciplinada nos referidos diplomas legais. A leitura isolada desse dispositivo poderia induzir a conclusão de que os motoristas que prestam serviços para empresas que exerçam atividades predominantemente rurais não seriam tutelados pelo aludido diploma legal e, por conseguinte, não se enquadrariam na categoria profissional diferenciada. Ocorre que a Lei nº 13.103/2015 introduziu o § 17 ao artigo 235-C da CLT, segundo o qual o "disposto no caput deste artigo aplica-se também aos operadores de automotores destinados a puxar ou a arrastar maquinaria de qualquer natureza ou a executar trabalhos de construção ou pavimentação e aos operadores de tratores, colheitadeiras, autopropelidos e demais aparelhos automotores destinados a puxar ou a arrastar maquinaria agrícola ou a executar trabalhos agrícolas". O caput do artigo 235-da CLT, por sua vez, traz a previsão de que a jornada de trabalho do motorista profissional será de oito horas, admitindo-se a sua prorrogação por até duas horas extraordinárias ou, desde que realizada por meio de negociação coletiva, por até quatro horas extraordinárias. Tem-se, desse modo, que foi estabelecida para os motoristas, tratoristas e operadores de máquinas em geral que laboram nas empresas agrícolas a mesma jornada dos demais motoristas profissionaisrodoviários. Permitiu-se, inclusive, a realização de quatro horas extraordinárias diárias, desde que autorizada por meio de instrumento de negociação coletiva. Desse modo, o legislador, ao determinar a aplicação do caput do artigo 235-C da CLT aos motoristas, tratoristas e operadores de máquinas em geral que laboram nas empresas agrícolas, reconheceu o enquadramento desses trabalhadores na categoria profissional diferenciada. É inequívoco que a legislação não autoriza a prorrogação da jornada de trabalho dos empregados rurais por até quatro horas, por meio de negociação coletiva. Segundo o artigo 7º, caput, do Decreto nº 73.626/1974, que regulamenta a Lei nº 5.889/1973, a "duração normal do trabalho poderá ser acrescida de horas suplementares, em número não excedente de 2 (duas), mediante acordo escrito entre o empregador e o empregado ou mediante contrato coletivo de trabalho, observado o disposto no artigo anterior". Constata-se que em nenhum dos dispositivos que disciplinam o trabalho extraordinário do empregado rural há autorização de prorrogação da jornada por até quatro horas por meio de negociação coletiva. Essa autorização é conferida apenas aos motoristas profissionais, ante a permissão legal de que os sindicatos representativos dessa categoria profissional transacionem a prorrogação da jornada. Desse modo, penso que, a se entender que os profissionais em discussão seriam representados pelo sindicato dos trabalhadores rurais, seria inócua a previsão contida no retrocitado preceito. Nesses temos, o Tribunal Regional, ao reconhecer que os motoristas, tratoristas e operadores de máquinas que laboram para a reclamada não se enquadram na categoria profissional diferenciada, violou o § 3º do artigo 511 da CLT. Recurso de revista de que se conhece e a que se dá provimento.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.7:acordao:2007-05-09;00178006320065010071', 'ACÓRDÃO TRT 1ª  / SÉTIMA TURMA / 0017800-63.2006.5.01.0071 - DOERJ 09-05-2007', 'urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.7:acordao:2007-05-09;00178006320065010071', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 1', 'Tribunal Regional Trabalho', 'Acordao', '2007-05-09', NULL, 'RODOVIÁRIOS- SUPRESSÃO DE  INTERVALOS INTRAJORNADA. EMBORA EXISTA AJUSTE PARA  PAGAMENTO  PELOS INTERVALOS NOS TERMOS DA CONVENÇÃO  COLETIVA DE  TRABALHO, EM DECORRÊNCIA DE TRANSAÇÃO HAVIDA ENTRE AS  PARTES, A  NORMA QUE REGULA O DESCANSO POSSUI CARÁTER  IMPERATIVO, OU  SEJA, É DE ORDEM PÚBLICA E SE CONSTITUI EM  GARANTIA MÍNIMA  ASSEGURADA AOS TRABALHADORES. PORTANTO,  INCONCEBÍVEL  A PRETENDIDA SUBSTITUIÇÃO DA NORMA QUE  OBRIGA A  CONCESSÃO DO INTERVALOS PELA CLÁUSULA QUE ESTABELECE A  OBRIGATORIEDADE DE DESCANSO ENTRE AS VIAGENS. TRATANDO-SE DE NORMAS DE  ORDEM PÚBLICA,  O DIPLOMA CONSOLIDADO ESTABELECE O  MÍNIMO, SENDO  QUE O SISTEMA DE PROTEÇÃO AO TRABALHO  SUBORDINADO  BUSCA, CALCADO EM SUA BASE DE PRINCÍPIOS, OIMPLEMENTODE  CONDIÇÕES SEMPRE MAIS VANTAJOSAS, SEJA POR MEIO  DA FUNÇÃO  LEGIFERANTE DO ESTADO, SEJA POR MEIO DE  NEGOCIAÇÃO  INDIVIDUAL OU COLETIVA. AMPARA NOSSO ENTENDIMENTO A  ORIENTAÇÃO JURISPRUDENCIAL N. 342, DA SDI-I DO COLENDO TST. A QUESTÃO AQUI SUB OCULIS NÃO  PASSA APENAS PELA  NECESSÁRIA PRESERVAÇÃO DA SAÚDE DO  OBREIRO. NÃO SE PODE PERDER DE VISTA QUE TRANSPORTE  COLETIVO É SERVIÇO PÚBLICO, E  QUE A SUPRESSÃO DO INTERVALO  MÍNIMO PRECONIZADO NOS  PRECITADOS DISPOSITIVOS PÕE EM RISCO A  POPULAÇÃO QUE TRANSITA NAS RUAS. USUÁRIOS DOS  TRANSPORTES COLETIVOS,  PEDESTRES, MOTORISTAS, ENFIM, TODOS,  INDISTINTAMENTE, SÃO EXPOSTOS AOS RISCOS JÁ TÃO ACENTUADOS  COMO OS QUE SÃO VIVIDOS ATUALMENTE NOS GRANDES  CENTROS URBANOS.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('implementos rodoviários', '2025-07-12 17:36:05', 'https://www.lexml.gov.br/urn/urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.7:acordao:2009-05-06;01227009520065010201', 'ACÓRDÃO TRT 1ª  / 7ª Turma / 0122700-95.2006.5.01.0201 - DOERJ 06-05-2009', 'urn:lex:br;justica.trabalho;regiao.1:tribunal.regional.trabalho;turma.7:acordao:2009-05-06;01227009520065010201', 'jurisprudence', 'br', NULL, NULL, 'Justiça Trabalho', 'Regiao 1', 'Tribunal Regional Trabalho', 'Acordao', '2009-05-06', NULL, 'RODOVIÁRIOS- SUPRESSÃO DE INTERVALOS INTRAJORNADA
Embora exista ajuste para pagamento pelos intervalos nos termos da Convenção Coletiva de Trabalho, em decorrência de transação havida entre as partes, a norma que regula o descanso possui caráter imperativo, ou seja, é de ordem pública e constitui-se em garantia mínima assegurada aos trabalhadores.  Portanto, inconcebível a pretendida substituição da norma que obriga a concessão do intervalos pela cláusula que estabelece a obrigatoriedade de descanso entre as viagens.
Tratando-se de normas de ordem pública, o diploma consolidado estabelece o mínimo, sendo que o sistema de proteção ao trabalho subordinado busca, calcado em sua base de princípios, oimplementode condições sempre mais vantajosas, seja por meio da função legisferante do Estado, seja por meio de negociação individual ou coletiva.
Ampara nosso entendimento a Orientação Jurisprudencial 342 da Seção de Dissídios Individuais - I do Tribunal Superior do Trabalho.
A questão aqui sub oculis não passa apenas pela necessária preservação da saúde do obreiro.  Não se pode perder de vista que transporte coletivo é serviço público e que a supressão do intervalo mínimo preconizado nos precitados dispositivos põe em risco a população que transita nas ruas. Usuários dos transportes coletivos, pedestres, motoristas, enfim, todos, indistintamente, são expostos aos riscos já tão acentuados como os que são vividos atualmente nos grandes centros urbanos.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
