INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('terminais de carga', '2025-07-12 17:35:57', 'https://www.lexml.gov.br/urn/urn:lex:br:superior.tribunal.justica;turma.1:acordao;resp:1997-11-07;128752-208914', 'REsp 128752 / RS', 'urn:lex:br:superior.tribunal.justica;turma.1:acordao;resp:1997-11-07;128752-208914', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Superior Tribunal Justica', 'Acordao;Resp', '1997-11-07', 'LEGALIDADE, ARRENDATARIO, PAGAMENTO, TARIFA,CARGA, DESCARGA,
EMBARCAÇÃO, PORTO DE USO PRIVATIVO, DECORRENCIA, CLAUSULA, CONTRATO,
OBSERVANCIA, LEGISLAÇÃO, EPOCA, CELEBRAÇÃO, NÃO CARACTERIZAÇÃO,
TRIBUTO, INAPLICABILIDADE, CODIGO TRIBUTARIO NACIONAL.
     DESCABIMENTO, MANDADO DE SEGURANÇA, DISCUSSÃO, EXIGIBILIDADE,
PAGAMENTO, TARIFA,CARGA, DESCARGA, EMBARCAÇÃO, PORTO, HIPOTESE,
ATRIBUIÇÃO, AUTORIDADE COATORA, EXECUÇÃO, CLAUSULA, CONTRATO, FALTA,
COMPETENCIA, SUSTAÇÃO, PAGAMENTO.
     DESCABIMENTO, MANDADO DE SEGURANÇA, APRECIAÇÃO, MORA,
AUTORIDADE ADMINISTRATIVA, DECORRENCIA, DECURSO DE PRAZO, FIXAÇÃO,
DECRETO, OBJETIVO, ALTERAÇÃO, TARIFA,CARGA, DESCARGA, PORTO,
NECESSIDADE, DILAÇÃO PROBATORIA.', 'DIREITO CIVIL.TERMINALPORTUARIA PAGA PELO ACOSTAMENTODEEMBARCAÇÃO PARACARGAE DESCARGA. DECRETO-LEI NUM. 83/66 E LEI
NUM. 8.630/93. LEGALIDADE.
NÃO E ILEGAL O PAGAMENTO DE TARIFA POR EMPRESA QUE EXPLORATERMINALPORTUARIO PRIVATIVO, SEMPRE QUE HOUVER  ACOSTAMENTO DE
EMBARCAÇÃO PARA EFEITO DE OPERAÇÕESDECARGAE DESCARGA NO
RESPECTIVOTERMINALMARITIMO (DECRETO-LEI NUM. 83/66), E PACTUADA
LIVREMENTE COM O DEPARTAMENTO DE PORTOS, RIOS E CANAIS (DEPRC),
NA FORMA DA LEGISLAÇÃO EM VIGOR.
NÃO PADECE DE ILEGITIMIDADE, QUE JUSTIFIQUE A SUA REPARAÇÃO PELA
VIA DE SEGURANÇA, O ATO DE AUTORIDADE QUE BUSCA O CUMPRIMENTO DE
CLAUSULA CONTRATUAL LIVREMENTE CELEBRADA EM OBEDIENCIA A
LEGISLAÇÃO PERTINENTE.
DESCABE MANDADO DE SEGURANÇA CONTRA AUTORIDADE CUJA FUNÇÃO E DE
MERA EXECUTORA DE CONTRATO, CARECENDO DE COMPETENCIA PARA SANAR A
POSSIVEL ILEGALIDADE DO ATO QUE SE PRETENDE ACOIMADO DE
IRREGULARIDADE CAPAZ DE INEFICACIZA-LO.
RECURSO IMPROVIDO. DECISÃO INDISCREPANTE.
Decisão
POR UNANIMIDADE, NEGAR PROVIMENTO AO RECURSO.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('benefício tributário', '2025-07-12 17:36:11', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2024;1227', '[ Medida Provisória nº 1227/2024 ]', 'urn:lex:br:congresso.nacional:medida.provisoria;mpv:2024;1227', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Congresso Nacional', '2024-01-01', NULL, 'Prevê condições para fruição debenefíciosfiscais, delega competência para julgamento de processo administrativo fiscal relativo ao Imposto sobre a Propriedade Territorial Rural - ITR, limita a compensação de créditos relativos a tributos administrados pela Secretaria Especial da Receita Federal do Brasil do Ministério da Fazenda e revoga hipóteses de ressarcimento e de compensação de créditos presumidos da Contribuição para o PIS/Pasep e da Cofins.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('benefício tributário', '2025-07-12 17:36:11', 'https://www.lexml.gov.br/urn/urn:lex:br:congresso.nacional:medida.provisoria;mpv:2023-12-29;1202', 'MPV 1202/2023', 'urn:lex:br:congresso.nacional:medida.provisoria;mpv:2023-12-29;1202', 'legislation', 'br', NULL, NULL, NULL, NULL, NULL, 'Congresso Nacional', '2023-12-29', NULL, 'Revoga osbenefíciosfiscais de que tratam o art. 4º da Lei nº 14.148, de 3 de maio de 2021, e os art. 7º a art. 10 da Lei nº 12.546, de 14 de dezembro de 2011, desonera parcialmente a contribuição previdenciária sobre a folha de pagamento, revoga a alíquota reduzida da contribuição previdenciária aplicável a determinados Municípios e limita a compensação de créditos decorrentes de decisões judiciais transitadas em julgado.

NOVA EMENTA: Altera a Lei nº 9.430, de 27 de dezembro de 1996, para limitar a compensaçãotributáriados créditos decorrentes de decisões judiciais transitadas em julgado.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
