INSERT INTO lexml_documents_corrected (search_term, date_searched, url, title, urn, urn_type, country, state, municipality, justice, region, court_class, document_type_full, enacting_date, document_description, document_summary, source_type, document_number) VALUES ('rotulagem veicular', '2025-07-12 17:36:06', 'https://www.lexml.gov.br/urn/urn:lex:br:supremo.tribunal.federal;turma.1:acordao;ai:2012-05-22;842865-4157324', 'AI 842865 AgR / PR - PARANÁ', 'urn:lex:br:supremo.tribunal.federal;turma.1:acordao;ai:2012-05-22;842865-4157324', 'jurisprudence', 'br', NULL, NULL, NULL, NULL, 'Supremo Tribunal Federal', 'Acordao;Ai', '2012-05-22', NULL, 'Ementa: AGRAVO REGIMENTAL NO AGRAVO DE INSTRUMENTO. AÇÃO CIVIL PÚBLICA. CONSUMO DE BEBIDAS ALCOÓLICAS. DANOS CAUSADOS. AUSÊNCIA DO NECESSÁRIO PREQUESTIONAMENTO. SÚMULAS 282 E 356 DO STF. INTERPRETAÇÃO DE LEGISLAÇÃO INFRACONSTITUCIONAL.



    1. O requisito do prequestionamento é indispensável, por isso que inviável a apreciação, em sede de recurso extraordinário, de matéria sobre a qual não se pronunciou o Tribunal de origem, incidindo os óbices das Súmulas 282 e 356 do Supremo Tribunal Federal. 



    2. A violação reflexa e oblíqua da Constituição Federal decorrente da necessidade de análise de malferimento de dispositivo infraconstitucional torna inadmissível o recurso extraordinário. Precedentes: RE 596.682, Rel. Min. Carlos Britto, Dje de 21/10/10, e o AI 808.361, Rel. Min. Marco Aurélio, Dje de 08/09/10.



    3. In casu, o acórdão recorrido assentou: “AÇÃO CIVIL PÚBLICA. DIREITO DO CONSUMIDOR. CORRETA A INFORMAÇÃO ACERCA DOS RISCOS E POTENCIAIS DANOS QUE O CONSUMO DE BEBIDAS ALCÓOLICAS CAUSA À SAÚDE. INSCRIÇÃO NECESSÁRIA NOS RÓTULOS DE BEBIDAS ALCÓOLICAS. 1. É possível e exigível do Judiciário, impor determinada conduta ao fornecedor, sem que esta esteja expressamente prevista em lei, desde que afinada com as políticas públicas diretamente decorrentes do texto constitucional e do princípio da plena informação ao consumidor (art. 6º, II, III e IV, da Lei 8.078/90, pois traduz-se em dever do Estado, do qual o Judiciário é poder, de acordo com o art. 196 da Constituição. 2. O consumo de alcoólicos não interessa só à comunicação social, propaganda e ao comércio de tais produtos, interessa sob o aspecto da saúde pública, da proteção do menor e do adolescente, da segurançaveicular, do direito de informação e de proteção ao consumidor. 3. O comando do art. 9º, do Código do Consumidor, indica os direitos básicos do consumidor à informação adequada e clara sobre o produto e sobre os riscos que apresenta, sobretudo, tratando-se de produto potencialmente nocivo à saúde, cuja informação deve ser feita de maneira ostensiva, a despeito da previsão do art. 4º, § 2º da Lei 9.294/96 determinar que os rótulos de bebidas alcoólicas conterão advertência para que os consumidores evitem o consumo excessivo de álcool. 4. Inocorre preclusão de matéria que diz com as condições da ação, caso da legitimidade, sobretudo nas ações civis públicas onde se perseguem direitos difusos, cujo interesse depreende-se da propriedade, das relações privativas em geral, o que, in casu, revelou-se pelo interesse demonstrado pela embargante, tantas vezes reiterado de defender a posição dos associados que são fabricantes de bebidas, tese da co-ré União. 5. Condenada a ré União a exigir narotulagemde todas as bebidas alcoólicas produzidas ou comercializadas no território pátrio, do teor alcoólico e do alerta em expressão gráfica adequada, de que ‘O ÁLCOOL PODE CAUSAR DEPENDÊNCIA E EM EXCESSO É PRJUDICIAL À SAÚDE’ e a ABRABE a expedir esta informação a todas as suas associadas e comunicar aos produtores de alcoólicos, quanto à necessária adequação. 6. Provido o recurso.” 



    4. Agravo regimental a que se nega provimento.', NULL, NULL) ON CONFLICT (urn) DO NOTHING;
